//! E2E test verifying that devcel-runtime reads real bundles exported by devcel-core.
//!
//! Set `DEVCEL_TEST_BUNDLE` to the path of bundle JSON generated by
//! `devcel export runtime --out <file>`. Skip when unset (for real CI/local data).
//!
//! Example:
//!   devcel export runtime --out bundle.json --project <proj>
//!   DEVCEL_TEST_BUNDLE=bundle.json cargo test -p devcel-runtime --test e2e_bundle

use devcel_runtime::Snapshot;

#[test]
fn reads_real_exported_bundle() {
    let Ok(path) = std::env::var("DEVCEL_TEST_BUNDLE") else {
        eprintln!("Skipped because DEVCEL_TEST_BUNDLE is not set");
        return;
    };

    let json = std::fs::read_to_string(&path).expect("Could not read the bundle file");
    let snap = Snapshot::from_json(&json).expect("Failed to parse the actual bundle");

    // Verify that the manifest and basic structure can be read
    assert!(!snap.content_hash().is_empty(), "content_hash is empty");
    eprintln!(
        "project={} tables={} content_hash={}",
        snap.project_name,
        snap.tables.len(),
        snap.content_hash()
    );

    for t in &snap.tables {
        eprintln!(
            "  table {} rows={} cols={}",
            t.name,
            t.row_count,
            t.columns.len()
        );
        // Each table's indices agree with its row count
        for (i, id) in t.row_ids.iter().enumerate() {
            assert_eq!(t.row_by_id(id), Some(i), "Inconsistent UUID index: {id}");
        }
    }
}
